export const PLANT_GROWTH_DEVELOPMENT = [
// ============================================================
// SECTION 1: GROWTH
// ============================================================

  { id: 'g1', topic: 'growth', type: 'mcq', question: 'Growth in plants is best defined as', options: ['A reversible process that can be undone', 'An irreversible permanent increase in size of an organ or its parts, or of an entire organism', 'Only an increase in cell number', 'Only an increase in dry weight'], correctIndex: 1, explanation: 'Growth is an irreversible, permanent increase in size of an organ, its parts, or the whole organism.', difficulty: 'easy' },
  { id: 'g2', topic: 'growth', type: 'mcq', question: 'At the cellular level, growth is mainly the result of', options: ['Increase in the number and size of cells', 'Loss of water from cells only', 'Breakdown of cell walls', 'Decrease in protoplasm'], correctIndex: 0, explanation: 'Growth results from an increase in cell number (division) and an increase in cell size.', difficulty: 'easy' },
  { id: 'g3', topic: 'growth', type: 'mcq', question: 'Growth in plants is considered indeterminate and unlimited because', options: ['Plants lack meristems', 'Plants retain the capacity for unlimited growth due to the presence of meristems throughout life', 'All plant cells continuously divide', 'Plants stop growing after reaching maturity'], correctIndex: 1, explanation: 'Due to the presence of meristems at certain locations, plants have the capacity for unlimited growth throughout their life — a phenomenon called open growth.', difficulty: 'medium' },
  { id: 'g4', topic: 'growth', type: 'mcq', question: 'Meristems responsible for growth in length of the plant body are located at the', options: ['Base of leaves only', 'Apices of root and shoot (apical meristems)', 'Nodes of stem only', 'Outer bark'], correctIndex: 1, explanation: 'Apical meristems, present at the tips of roots and shoots, add cells that increase the length of the plant body.', difficulty: 'easy' },
  { id: 'g5', topic: 'growth', type: 'mcq', question: 'Growth arising from the activity of intercalary meristems is best exemplified by', options: ['Growth at the leaf base in grasses', 'Growth at the root tip', 'Growth at the shoot apex', 'Secondary growth in dicot stems'], correctIndex: 0, explanation: 'Intercalary meristems, found at the base of leaves or internodes (e.g. in grasses), contribute to growth in length.', difficulty: 'medium' },
  { id: 'g6', topic: 'growth', type: 'mcq', question: 'Growth in girth (width) of woody dicot stems is chiefly due to the activity of', options: ['Apical meristem', 'Lateral meristems (vascular cambium and cork cambium)', 'Intercalary meristem', 'Root cap'], correctIndex: 1, explanation: 'Lateral meristems such as the vascular cambium and cork cambium bring about an increase in girth (secondary growth).', difficulty: 'medium' },
  { id: 'g7', topic: 'growth', type: 'mcq', question: 'A growing root tip can be divided into distinct phases of growth. Which is the correct order of these phases from the tip inward?', options: ['Maturation, elongation, meristematic', 'Meristematic, elongation, maturation', 'Elongation, meristematic, maturation', 'Meristematic, maturation, elongation'], correctIndex: 1, explanation: 'From the root tip inward, the order of phases is meristematic zone, followed by the elongation zone, followed by the maturation zone.', difficulty: 'medium' },
  { id: 'g8', topic: 'growth', type: 'mcq', question: 'Cells in the meristematic phase of growth are characterised by', options: ['Large vacuoles and thick walls', 'Rich protoplasm, large conspicuous nuclei, thin cellulosic walls, and dense cytoplasm', 'Complete loss of the nucleus', 'Highly lignified secondary walls'], correctIndex: 1, explanation: 'Meristematic cells are small, densely cytoplasmic, with large nuclei and thin walls, actively dividing.', difficulty: 'medium' },
  { id: 'g9', topic: 'growth', type: 'mcq', question: 'The phase of growth immediately following the meristematic phase, marked by an increase in vacuolation and cell size, is the', options: ['Maturation phase', 'Elongation phase', 'Senescence phase', 'Meristematic phase'], correctIndex: 1, explanation: 'Cells proximal to the meristematic zone constitute the elongation phase, showing increased vacuolation and cell enlargement.', difficulty: 'easy' },
  { id: 'g10', topic: 'growth', type: 'mcq', question: 'The phase of growth in which cells attain their maximal size and become differentiated with thickened walls is the', options: ['Meristematic phase', 'Elongation phase', 'Maturation phase', 'Lag phase'], correctIndex: 2, explanation: 'In the maturation phase, cells attain their maximum size, undergo differentiation, and often develop thickened, specialised walls.', difficulty: 'easy' },
  { id: 'g11', topic: 'growth', type: 'assertion-reason', question: 'Assertion (A): Growth is generally measured as an increase in dry weight rather than fresh weight.\nReason (R): Fresh weight fluctuates greatly with the water content of the tissue, making it a less reliable measure of growth.', options: AR_OPTIONS, correctIndex: 0, explanation: 'Because fresh weight varies with water content, dry weight is often the more consistent and preferred measure, directly justifying the assertion.', difficulty: 'medium' },
  { id: 'g12', topic: 'growth', type: 'mcq', question: 'Which of the following is NOT typically used as a parameter to measure plant growth?', options: ['Increase in length or area', 'Increase in fresh or dry weight', 'Increase in cell number', 'Change in flower colour'], correctIndex: 3, explanation: 'Growth is quantified by increases in length, area, weight, volume, or cell number — not by colour changes.', difficulty: 'easy' },
  { id: 'g13', topic: 'growth', type: 'mcq', question: 'Growth in which an organ increases in size by an equal amount per unit time, producing a linear graph, is called', options: ['Geometric growth', 'Arithmetic growth', 'Exponential growth', 'Sigmoid growth'], correctIndex: 1, explanation: 'In arithmetic growth, one daughter cell continues to divide while the other differentiates, producing a constant increase in length over time, shown as a linear curve.', difficulty: 'medium' },
  { id: 'g14', topic: 'growth', type: 'mcq', question: 'The mathematical expression for arithmetic growth is Lt = L0 + rt, where "r" represents the', options: ['Growth rate per unit time', 'Final length only', 'Initial length only', 'Volume of the organ'], correctIndex: 0, explanation: 'In Lt = L0 + rt, "r" is the constant growth rate over time "t", added to the initial length L0.', difficulty: 'hard' },
  { id: 'g15', topic: 'growth', type: 'mcq', question: 'A classic example of arithmetic growth is', options: ['A growing population of bacteria', 'A root elongating at a constant rate', 'Fruit ripening', 'Seed dormancy'], correctIndex: 1, explanation: 'A root elongating at a constant rate over time is a typical example of arithmetic growth.', difficulty: 'easy' },
  { id: 'g16', topic: 'growth', type: 'mcq', question: 'In geometric growth, the initial growth is slow (lag phase) and then increases rapidly, often at an exponential rate; this rapid phase is called the', options: ['Stationary phase', 'Log (exponential) phase', 'Senescence phase', 'Dormant phase'], correctIndex: 1, explanation: 'The rapid growth phase following the initial lag phase in geometric growth is called the log or exponential phase.', difficulty: 'medium' },
  { id: 'g17', topic: 'growth', type: 'mcq', question: 'The typical growth curve obtained when both starting phases of geometric growth are plotted against time is described as', options: ['A straight line', 'A sigmoid (S-shaped) curve', 'A parabola', 'A perfectly circular graph'], correctIndex: 1, explanation: 'Geometric growth, when plotted against time, produces a characteristic sigmoid or S-shaped curve with lag, log, and stationary phases.', difficulty: 'medium' },
  { id: 'g18', topic: 'growth', type: 'mcq', question: 'The three phases of the sigmoid growth curve, in order, are', options: ['Log phase, lag phase, stationary phase', 'Lag phase, log (exponential) phase, stationary phase', 'Stationary phase, lag phase, log phase', 'Log phase, stationary phase, lag phase'], correctIndex: 1, explanation: 'The sigmoid growth curve has an initial lag phase, followed by a rapid log/exponential phase, and finally a stationary phase.', difficulty: 'medium' },
  { id: 'g19', topic: 'growth', type: 'mcq', question: 'The exponential growth equation W1 = W0 * e^(rt) uses "r" to represent the', options: ['Final weight', 'Relative growth rate (efficiency index)', 'Time in days only', 'Base of natural logarithm'], correctIndex: 1, explanation: 'In the exponential growth formula, "r" denotes the relative growth rate, also referred to as the efficiency index.', difficulty: 'hard' },
  { id: 'g20', topic: 'growth', type: 'mcq', question: 'Relative growth rate is defined as the', options: ['Growth of the given organ per unit initial size', 'Total growth of an organ regardless of size', 'Growth measured only in weight terms', 'Growth measured only at maturity'], correctIndex: 0, explanation: 'The relative growth rate expresses the increase in growth of a given system per unit time, relative to its initial value.', difficulty: 'medium' },
  { id: 'g21', topic: 'growth', type: 'assertion-reason', question: 'Assertion (A): Two leaves of a plant that are of the same size may show a difference in their absolute growth rate.\nReason (R): Absolute growth rate is the total growth (increase) per unit time, which can differ due to differing efficiencies even if starting sizes are similar.', options: AR_OPTIONS, correctIndex: 0, explanation: 'Since absolute growth rate measures total increase per unit time, two organs starting at similar sizes can still show different absolute growth if their growth efficiency differs, supporting the assertion.', difficulty: 'hard' },
  { id: 'g22', topic: 'growth', type: 'mcq', question: 'The comparison between the total growth per unit time of two leaves of unequal size is best made using', options: ['Absolute growth rate', 'Relative growth rate', 'Arithmetic growth rate only', 'Weight of leaf alone'], correctIndex: 1, explanation: 'Relative growth rate allows meaningful comparison of growth between organs of different initial sizes, unlike absolute growth rate.', difficulty: 'medium' },
  { id: 'g23', topic: 'growth', type: 'mcq', question: 'Which of the following is essential for plant growth to occur?', options: ['Darkness at all times', 'Water, oxygen, nutrients, and a favourable temperature', 'Complete absence of nutrients', 'Constant freezing temperature'], correctIndex: 1, explanation: 'Growth in plants requires water, oxygen, nutrients, and optimum temperature among other favourable conditions.', difficulty: 'easy' },
  { id: 'g24', topic: 'growth', type: 'mcq', question: 'Water is essential for growth mainly because it', options: ['Provides the medium for cell elongation via turgidity and enables metabolic activities', 'Directly forms new cell walls', 'Prevents transpiration completely', 'Provides carbon for photosynthesis'], correctIndex: 0, explanation: 'Water provides the necessary turgidity for cell elongation and is required for various metabolic activities that drive growth.', difficulty: 'medium' },
  { id: 'g25', topic: 'growth', type: 'mcq', question: 'Every plant has an optimum, minimum, and maximum temperature range for growth; this concept is referred to as', options: ['Photoperiodism', 'Cardinal temperatures for growth', 'Vernalization', 'Thermoperiodicity of flowering only'], correctIndex: 1, explanation: 'The minimum, optimum, and maximum temperatures needed for growth of a plant species are together termed cardinal temperatures.', difficulty: 'medium' },
  { id: 'g26', topic: 'growth', type: 'statement', question: 'Consider the following statements about plant growth:\n1. Growth is theoretically unlimited in most plants due to meristems.\n2. Growth always occurs at a constant, unchanging rate.\n3. Growth requires favourable temperature, water, oxygen and nutrients.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '1 and 3 only', '2 and 3 only', '1, 2 and 3'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct; growth rate is not constant — it varies (as seen in the sigmoid curve), so statement 2 is incorrect.', difficulty: 'medium' },
  { id: 'g27', topic: 'growth', type: 'count-correct', question: 'How many of the following are examples of meristems responsible for plant growth?\n(i) Apical meristem\n(ii) Intercalary meristem\n(iii) Lateral meristem\n(iv) Malpighian meristem (not a real term)', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Apical, intercalary, and lateral meristems are real meristem types in plants; "Malpighian meristem" is not a recognised term.', difficulty: 'medium' },
  { id: 'g28', topic: 'growth', type: 'mcq', question: 'The zone of a growing root nearest the root tip, responsible for protecting the meristem, is the', options: ['Zone of elongation', 'Zone of maturation', 'Root cap', 'Zone of differentiation only'], correctIndex: 2, explanation: 'The root cap, located at the extreme tip, protects the delicate apical meristem as the root pushes through soil.', difficulty: 'easy' },
  { id: 'g29', topic: 'growth', type: 'mcq', question: 'Growth measured as increase in the number of cells is most useful when studying', options: ['A whole mature tree', 'A population of dividing cells, such as in tissue culture', 'A single non-dividing mature leaf', 'A dormant seed'], correctIndex: 1, explanation: 'Cell number as a growth parameter is especially useful in actively dividing systems such as cell or tissue cultures.', difficulty: 'medium' },
  { id: 'g30', topic: 'growth', type: 'matching', question: 'Match the phase of growth in Column I with its characteristic feature in Column II.\nColumn I: A. Meristematic phase, B. Elongation phase, C. Maturation phase\nColumn II: (i) Cells attain maximum size and specialised wall thickenings, (ii) Dense cytoplasm and active cell division, (iii) Increased vacuolation and cell enlargement', options: ['A-ii, B-iii, C-i', 'A-i, B-ii, C-iii', 'A-iii, B-i, C-ii', 'A-ii, B-i, C-iii'], correctIndex: 0, explanation: 'Meristematic phase = active division/dense cytoplasm; elongation phase = vacuolation/enlargement; maturation phase = maximum size and wall thickening.', difficulty: 'medium' },
  { id: 'g31', topic: 'growth', type: 'mcq', question: 'The vascular cambium and cork cambium are collectively examples of which type of meristem?', options: ['Apical meristem', 'Intercalary meristem', 'Lateral meristem', 'Ground meristem'], correctIndex: 2, explanation: 'Vascular cambium and cork cambium are lateral meristems, positioned parallel to the sides of stems and roots, responsible for secondary growth.', difficulty: 'medium' },
  { id: 'g32', topic: 'growth', type: 'mcq', question: 'Growth rate is defined as the', options: ['Total final size of an organ', 'Growth per unit time', 'Weight lost during senescence', 'Colour change over time'], correctIndex: 1, explanation: 'Growth rate is simply the increase in growth parameters (length, weight, number) per unit time.', difficulty: 'easy' },
  { id: 'g33', topic: 'growth', type: 'mcq', question: 'A plant growing in the exponential (log) phase shows', options: ['A constant rate of increase', 'A rate of growth that increases with time (compounding growth)', 'No growth at all', 'Only a decrease in cell number'], correctIndex: 1, explanation: 'In the exponential phase, the growth rate itself increases progressively with time, similar to compound interest.', difficulty: 'medium' },
  { id: 'g34', topic: 'growth', type: 'assertion-reason', question: 'Assertion (A): Arithmetic growth produces a linear curve when plotted against time.\nReason (R): In arithmetic growth, only one daughter cell continues to divide after mitosis, while the other elongates and differentiates.', options: AR_OPTIONS, correctIndex: 0, explanation: 'Because only one daughter cell keeps dividing while the other matures, growth occurs at a constant rate, producing a linear (straight-line) curve — this directly explains the assertion.', difficulty: 'hard' },
  { id: 'g35', topic: 'growth', type: 'mcq', question: 'The stationary phase of the sigmoid growth curve occurs when', options: ['Growth is at its fastest rate', 'Growth rate slows down as nutrients or other factors become limiting', 'Cell division has just begun', 'The organism experiences maximum food supply with no limits'], correctIndex: 1, explanation: 'The stationary phase reflects slowed growth as resources (nutrients, space, etc.) become limiting.', difficulty: 'medium' },
  { id: 'g36', topic: 'growth', type: 'mcq', question: 'Which of these is generally true for growth measurement in plants using length as a parameter?', options: ['It can only be applied to roots', 'It is a simple, commonly used way to quantify growth in an organ like a leaf or stem', 'It cannot be used at all for young seedlings', 'It requires destruction of the plant tissue'], correctIndex: 1, explanation: 'Increase in length is one of the simplest and most common ways to quantify growth in various plant organs.', difficulty: 'easy' },
  { id: 'g37', topic: 'growth', type: 'mcq', question: 'When growth rate is expressed mathematically per unit time on an existing base, this is called the', options: ['Efficiency index', 'Absolute rate only', 'Colour index', 'Photoperiod'], correctIndex: 0, explanation: 'The relative growth rate is also known as the efficiency index, since it reflects growth relative to existing size.', difficulty: 'hard' },
  { id: 'g38', topic: 'growth', type: 'mcq', question: 'In a growing plant, cell division at the apical meristem is followed almost immediately by', options: ['Maturation of the newly formed cells', 'Cell enlargement in the region of elongation', 'Death of the meristematic cells', 'Formation of secondary xylem'], correctIndex: 1, explanation: 'Newly divided cells first pass through the elongation phase, enlarging in size before differentiating.', difficulty: 'medium' },
  { id: 'g39', topic: 'growth', type: 'count-correct', question: 'How many of the following growth parameters can be used to measure plant growth?\n(i) Increase in fresh weight\n(ii) Increase in dry weight\n(iii) Increase in length\n(iv) Increase in cell number\n(v) Change in leaf colour due to season', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 2, explanation: 'Fresh weight, dry weight, length, and cell number are valid growth parameters; seasonal colour change is unrelated to growth measurement.', difficulty: 'medium' },
  { id: 'g40', topic: 'growth', type: 'mcq', question: 'The zone of elongation in a root is typically located', options: ['At the extreme tip, beyond the root cap', 'Just proximal to (behind) the meristematic zone', 'At the region of root hairs only', 'In the mature vascular tissue'], correctIndex: 1, explanation: 'The elongation zone lies just behind (proximal to) the meristematic zone in the growing root.', difficulty: 'medium' },
  { id: 'g41', topic: 'growth', type: 'mcq', question: 'A key feature distinguishing arithmetic from geometric growth is that', options: ['Arithmetic growth shows a curve that keeps rising exponentially', 'Geometric growth involves both a slow initial phase and a fast phase, unlike the constant-rate arithmetic growth', 'Arithmetic growth only occurs in animals', 'Geometric growth never has a stationary phase'], correctIndex: 1, explanation: 'Geometric growth has a lag phase followed by an accelerating log phase, unlike the steady, constant-rate pattern of arithmetic growth.', difficulty: 'medium' },
  { id: 'g42', topic: 'growth', type: 'mcq', question: 'Which of the following best explains why most natural growth in nutrient-limited environments eventually deviates from a purely exponential pattern?', options: ['Nutrients become depleted, or other limiting factors slow the rate, leading to a stationary phase', 'Growth rate always remains exponential forever', 'Cells stop needing nutrients after a while', 'Plants switch from geometric to arithmetic growth automatically after maturity'], correctIndex: 0, explanation: 'Limited resources eventually cause a slowdown in growth rate, producing the plateau or stationary phase of the sigmoid curve.', difficulty: 'hard' },
  { id: 'g43', topic: 'growth', type: 'mcq', question: 'Growth measured in terms of volume is particularly useful for studying', options: ['Leaves only', 'Fleshy fruits or storage organs like tubers', 'Root hairs specifically', 'Pollen tubes exclusively'], correctIndex: 1, explanation: 'Volume is a convenient growth parameter for fleshy structures such as fruits and storage organs like tubers.', difficulty: 'medium' },
  { id: 'g44', topic: 'growth', type: 'mcq', question: 'The term "growth rate" implies growth', options: ['Measured without reference to time', 'Per unit of time', 'Measured only once in a plant\'s life', 'Only applicable to seed germination'], correctIndex: 1, explanation: 'Growth rate specifically denotes the increase in growth parameters per unit of time.', difficulty: 'easy' },
  { id: 'g45', topic: 'growth', type: 'mcq', question: 'Which factor is generally NOT considered essential merely for germination but is more relevant to subsequent growth?', options: ['Water', 'Oxygen', 'Light, in the case of non-photoblastic seeds', 'Favourable temperature'], correctIndex: 2, explanation: 'Many seeds are non-photoblastic and can germinate without light, whereas water, oxygen, and temperature are broadly essential for germination and growth.', difficulty: 'hard' },
  { id: 'g46', topic: 'growth', type: 'mcq', question: 'The concept of "open growth" in plants refers to the fact that', options: ['Plants grow only in open sunlight', 'New cells are constantly added throughout life by meristems, unlike the fixed body form of most animals', 'Plant cells lack cell walls', 'Growth stops once flowering begins'], correctIndex: 1, explanation: 'Open growth describes how meristems continuously add new cells and structures throughout a plant\'s life, unlike the largely fixed (closed) growth pattern of most animals.', difficulty: 'medium' },
  { id: 'g47', topic: 'growth', type: 'assertion-reason', question: 'Assertion (A): The growth of a plant organ, unlike that of most animals, occurs indefinitely.\nReason (R): Meristematic tissue in plants retains the capacity to divide throughout the life of the plant.', options: AR_OPTIONS, correctIndex: 0, explanation: 'The continued division capacity of meristematic tissue directly explains the indeterminate, unlimited growth pattern characteristic of plants.', difficulty: 'medium' },
  { id: 'g48', topic: 'growth', type: 'mcq', question: 'The formula Lt = L0 * e^(rt) is used to represent', options: ['Arithmetic growth', 'Geometric (exponential) growth', 'Growth only during dormancy', 'Growth of a single cell only, never populations'], correctIndex: 1, explanation: 'Lt = L0 * e^(rt) is the mathematical expression used for geometric (exponential) growth.', difficulty: 'hard' },
  { id: 'g49', topic: 'growth', type: 'mcq', question: 'In a bean seedling, the two cotyledons unequal in growth over time — one growing faster relative to its size than the other of similar starting size — would best be compared using', options: ['Absolute growth rate', 'Relative growth rate', 'Only fresh weight', 'Only dry weight'], correctIndex: 1, explanation: 'When comparing organs based on how fast they grow relative to their own initial size, relative growth rate is the appropriate measure.', difficulty: 'medium' },
  { id: 'g50', topic: 'growth', type: 'mcq', question: 'Root hairs, formed in the maturation zone of a root, primarily aid in', options: ['Cell division', 'Absorption of water and minerals', 'Photosynthesis', 'Storage of starch only'], correctIndex: 1, explanation: 'Root hairs, arising in the maturation zone, greatly increase the surface area for absorption of water and minerals.', difficulty: 'easy' },
  { id: 'g51', topic: 'growth', type: 'mcq', question: 'Compared to a slow-growing plant of similar age, a fast-growing plant under the same conditions would generally show', options: ['A lower absolute growth rate', 'A higher absolute growth rate', 'No difference in any growth parameter', 'Growth only during the night'], correctIndex: 1, explanation: 'A faster-growing plant naturally shows a higher increase (absolute growth rate) per unit time.', difficulty: 'easy' },
  { id: 'g52', topic: 'growth', type: 'statement', question: 'Consider the following statements about growth measurement:\n1. Dry weight is generally a more stable growth indicator than fresh weight.\n2. Relative growth rate accounts for the initial size of the organ being measured.\n3. Absolute growth rate and relative growth rate always give identical values.\nWhich of the statements given above are correct?', options: ['1 only', '1 and 2 only', '2 and 3 only', '1, 2 and 3'], correctIndex: 1, explanation: 'Statements 1 and 2 correctly describe growth measurement; statement 3 is incorrect since absolute and relative growth rates measure different things and are generally not identical.', difficulty: 'medium' },
  { id: 'g53', topic: 'growth', type: 'mcq', question: 'The primary function of the meristematic zone at a root or shoot tip is to', options: ['Store food reserves', 'Continuously produce new cells through mitotic division', 'Conduct water upward', 'Absorb minerals from soil'], correctIndex: 1, explanation: 'The meristematic zone is the site of active mitotic division, continually generating new cells for growth.', difficulty: 'easy' },
  { id: 'g54', topic: 'growth', type: 'count-correct', question: 'How many of the following statements about growth phases are correct?\n(i) The meristematic phase shows dense cytoplasm and thin walls.\n(ii) The elongation phase shows increased vacuolation.\n(iii) The maturation phase precedes the elongation phase.\n(iv) The maturation phase shows differentiation and wall thickening.', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements (i), (ii), and (iv) are correct; the maturation phase actually follows, not precedes, the elongation phase, so (iii) is incorrect.', difficulty: 'medium' },
  { id: 'g55', topic: 'growth', type: 'mcq', question: 'The primary growth of a plant, contributing to increase in length, is due to the activity of', options: ['Apical and intercalary meristems', 'Only lateral meristems', 'Only cork cambium', 'Only vascular cambium'], correctIndex: 0, explanation: 'Primary growth, which increases the length of roots and shoots, results from apical meristem activity and, in some plants, intercalary meristems.', difficulty: 'medium' },

// ============================================================
// SECTION 2: DIFFERENTIATION, DEDIFFERENTIATION, REDIFFERENTIATION, DEVELOPMENT 
// ============================================================

  { id: 'd1', topic: 'differentiation', type: 'mcq', question: 'Differentiation in plants refers to the process by which', options: ['Cells lose water permanently', 'Cells derived from meristems undergo structural and functional changes to perform specific functions', 'Cells revert back to a meristematic state', 'Cells die and are shed'], correctIndex: 1, explanation: 'Differentiation is the process by which cells derived from root/shoot apical meristems and cambium mature to perform specific functions.', difficulty: 'easy' },
  { id: 'd2', topic: 'differentiation', type: 'mcq', question: 'During differentiation, cells often undergo changes such as', options: ['Complete loss of the cell wall', 'Distinctive thickening of the cell wall and specific changes in cytoplasm to perform specific functions', 'Reversal to embryonic state', 'Only an increase in nuclear size with no other change'], correctIndex: 1, explanation: 'Differentiating cells undergo wall thickening and cytoplasmic modification suited to their eventual specific function.', difficulty: 'medium' },
  { id: 'd3', topic: 'differentiation', type: 'mcq', question: 'The formation of tracheary elements (xylem vessels), which lack protoplasm at maturity and have thick, lignified walls, is an example of', options: ['Dedifferentiation', 'Differentiation', 'Redifferentiation only', 'Senescence'], correctIndex: 1, explanation: 'The specialisation of cells into tracheary elements, adapted for water conduction, is a classic example of differentiation.', difficulty: 'medium' },
  { id: 'd4', topic: 'differentiation', type: 'mcq', question: 'Living, differentiated cells that regain the capacity to divide under certain conditions undergo a process called', options: ['Differentiation', 'Dedifferentiation', 'Redifferentiation', 'Senescence'], correctIndex: 1, explanation: 'Dedifferentiation is the process by which differentiated, living cells regain the capacity to divide.', difficulty: 'easy' },
  { id: 'd5', topic: 'differentiation', type: 'mcq', question: 'The formation of interfascicular cambium from mature, living parenchyma cells is an example of', options: ['Differentiation', 'Dedifferentiation', 'Senescence', 'Abscission'], correctIndex: 1, explanation: 'Interfascicular cambium forms from parenchyma cells that regain dividing capacity, illustrating dedifferentiation.', difficulty: 'medium' },
  { id: 'd6', topic: 'differentiation', type: 'mcq', question: 'When the tissues produced by dedifferentiated cells (such as the interfascicular or cork cambium) mature and lose the ability to divide, taking up a specific function, this is termed', options: ['Redifferentiation', 'Dedifferentiation', 'Vernalization', 'Photoperiodism'], correctIndex: 0, explanation: 'Redifferentiation refers to the maturation of cells produced by dedifferentiated tissue into cells that once again perform a specific function.', difficulty: 'medium' },
  { id: 'd7', topic: 'differentiation', type: 'mcq', question: 'Cork cambium (phellogen) forming secondary cortex and cork tissue that mature to protect the stem is a good example of', options: ['Only dedifferentiation', 'Both dedifferentiation and redifferentiation occurring in sequence', 'Photoperiodism', 'Only differentiation with no prior dedifferentiation'], correctIndex: 1, explanation: 'Parenchyma cells dedifferentiate to form cork cambium, and the tissues it produces then redifferentiate into cork and secondary cortex.', difficulty: 'hard' },
  { id: 'd8', topic: 'differentiation', type: 'assertion-reason', question: 'Assertion (A): Dedifferentiation is essential for wound healing and secondary growth in plants.\nReason (R): Dedifferentiation allows mature, living cells to regain the ability to divide and form new meristematic regions.', options: AR_OPTIONS, correctIndex: 0, explanation: 'The renewed ability of mature cells to divide directly enables processes like wound healing and secondary growth, correctly explaining the assertion.', difficulty: 'medium' },
  { id: 'd9', topic: 'differentiation', type: 'mcq', question: 'Development in a plant, as a broader concept, includes both', options: ['Only growth', 'Only differentiation', 'Growth and differentiation together, integrated in a well-coordinated manner', 'Only reproduction'], correctIndex: 2, explanation: 'Development encompasses all changes an organism undergoes through its life, integrating growth and differentiation.', difficulty: 'medium' },
  { id: 'd10', topic: 'differentiation', type: 'mcq', question: 'A plant\'s development results from two processes acting together on cells derived from apical meristems: growth and', options: ['Photoperiodism', 'Differentiation', 'Translocation', 'Transpiration'], correctIndex: 1, explanation: 'Development is the sum of growth and differentiation acting on the cells produced by meristems.', difficulty: 'easy' },
  { id: 'd11', topic: 'differentiation', type: 'mcq', question: 'The ability of plants to follow different pathways in response to environment or phases of life, forming structures suited to that environment, is termed', options: ['Vernalization', 'Plasticity', 'Photoperiodism', 'Senescence'], correctIndex: 1, explanation: 'Plasticity is the plant\'s ability to follow different developmental pathways in response to environmental conditions or life phase.', difficulty: 'medium' },
  { id: 'd12', topic: 'differentiation', type: 'mcq', question: 'Heterophylly, seen in some plants where leaf shape differs between juvenile and mature (or aquatic and aerial) leaves, is a good example of', options: ['Dedifferentiation', 'Plasticity in plant development', 'Vernalization', 'Redifferentiation'], correctIndex: 1, explanation: 'Heterophylly, where leaf shape changes with developmental phase or environment (e.g. cotton, coriander, larkspur, or buttercup), illustrates plasticity.', difficulty: 'medium' },
  { id: 'd13', topic: 'differentiation', type: 'mcq', question: 'In plants like cotton, coriander, and larkspur, juvenile leaves may differ in shape from mature leaves. This phenomenon is termed', options: ['Vernalization', 'Heterophylly', 'Ecdysis', 'Redifferentiation only'], correctIndex: 1, explanation: 'Heterophylly refers to the difference in leaf form during different developmental phases, seen in cotton, coriander, and larkspur.', difficulty: 'medium' },
  { id: 'd14', topic: 'differentiation', type: 'mcq', question: 'In heterophyllous aquatic plants such as buttercup (Ranunculus), leaf shape differs between', options: ['Different flower colours', 'Leaves formed in water versus those formed in air', 'Root and stem tissue', 'Male and female flowers only'], correctIndex: 1, explanation: 'In buttercup, leaves developed underwater are dissected/finely divided, while those formed in air are broader — an environmental response.', difficulty: 'hard' },
  { id: 'd15', topic: 'differentiation', type: 'mcq', question: 'Senescence in plants refers to', options: ['The initial phase of seed germination', 'A phase involving natural processes of deterioration that eventually lead to the death of a plant or plant part', 'Rapid cell division at the shoot tip', 'The onset of flowering'], correctIndex: 1, explanation: 'Senescence is the phase of natural ageing and deterioration, ultimately leading to death of an organ or organism.', difficulty: 'medium' },
  { id: 'd16', topic: 'differentiation', type: 'mcq', question: 'The shedding of leaves, flowers, or fruits from the plant body is termed', options: ['Vernalization', 'Abscission', 'Germination', 'Photoperiodism'], correctIndex: 1, explanation: 'Abscission refers to the natural detachment/shedding of plant organs like leaves, flowers, and fruits.', difficulty: 'easy' },
  { id: 'd17', topic: 'differentiation', type: 'statement', question: 'Consider the following statements:\n1. Differentiation involves cells losing the ability to divide as they mature.\n2. Dedifferentiation allows differentiated cells to regain the capacity to divide.\n3. Redifferentiation involves cells that never divided at all.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '2 and 3 only', '1 and 3 only', '1, 2 and 3'], correctIndex: 0, explanation: 'Statements 1 and 2 are correct; redifferentiation involves cells produced by dedifferentiated (previously dividing) tissue that then mature, so statement 3 is incorrect.', difficulty: 'medium' },
  { id: 'd18', topic: 'differentiation', type: 'count-correct', question: 'How many of the following are correctly matched?\n(i) Differentiation — Cells acquire specific structure and function\n(ii) Dedifferentiation — Living mature cells regain dividing capacity\n(iii) Redifferentiation — Cells lose the ability to differentiate permanently\n(iv) Plasticity — Different pathways followed in response to environment', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements (i), (ii), and (iv) are correctly matched; redifferentiation is the maturation of dedifferentiated tissue cells into a specific functional form, not a permanent loss of differentiation ability.', difficulty: 'hard' },
  { id: 'd19', topic: 'differentiation', type: 'mcq', question: 'Formation of secondary xylem and secondary phloem from the vascular cambium, which itself formed by dedifferentiation, is an example of', options: ['Redifferentiation', 'Only dedifferentiation, with no redifferentiation involved', 'Senescence', 'Abscission'], correctIndex: 0, explanation: 'Secondary xylem and phloem, formed by cambial cells maturing into specific cell types, exemplify redifferentiation.', difficulty: 'medium' },
  { id: 'd20', topic: 'differentiation', type: 'mcq', question: 'The specific form and structure that a mature cell attains, correlated with the function it will perform, is best described as', options: ['Vernalization', 'A specific outcome of differentiation', 'Photoperiodism', 'Abscission'], correctIndex: 1, explanation: 'The specialised structure a cell acquires that suits its function is the direct result of differentiation.', difficulty: 'easy' },
  { id: 'd21', topic: 'differentiation', type: 'assertion-reason', question: 'Assertion (A): A mature sieve tube element, unlike a xylem tracheid, retains living protoplasm at maturity.\nReason (R): Differentiation produces cell types with structural features specifically suited to their particular function.', options: AR_OPTIONS, correctIndex: 1, explanation: 'Both statements are factually true (sieve tubes are living, unlike dead tracheids), but the reason given is a general statement about differentiation rather than the specific explanation for why sieve tubes retain living protoplasm.', difficulty: 'hard' },
  { id: 'd22', topic: 'differentiation', type: 'mcq', question: 'Which of the following best describes the concept of "development" in plant biology?', options: ['Development is synonymous with growth alone', 'Development is the sum total of growth and differentiation, integrating both processes', 'Development refers only to seed formation', 'Development occurs only in animals, not plants'], correctIndex: 1, explanation: 'Development integrates growth and differentiation as the plant progresses through its life cycle.', difficulty: 'medium' },
  { id: 'd23', topic: 'differentiation', type: 'mcq', question: 'The two processes that together constitute plant development, and are regulated by intrinsic and extrinsic factors, are', options: ['Growth and differentiation', 'Photoperiodism and vernalization', 'Dormancy and germination only', 'Absorption and translocation'], correctIndex: 0, explanation: 'Growth and differentiation, occurring in a coordinated manner and regulated by internal and external factors, together constitute development.', difficulty: 'medium' },
  { id: 'd24', topic: 'differentiation', type: 'mcq', question: 'Internal (intrinsic) factors regulating plant development include', options: ['Only light and temperature', 'Intracellular factors (genetic) and intercellular factors such as plant growth regulators', 'Only soil pH', 'Only day length'], correctIndex: 1, explanation: 'Intrinsic factors include both intracellular (genetic) factors and intercellular factors like plant growth regulators.', difficulty: 'medium' },
  { id: 'd25', topic: 'differentiation', type: 'mcq', question: 'External (extrinsic) factors regulating plant development typically include', options: ['Light, temperature, water, oxygen, and nutrition', 'Only genetic composition of the plant', 'Only plant growth regulators', 'Only cell wall composition'], correctIndex: 0, explanation: 'Extrinsic factors affecting development include environmental variables like light, temperature, water, oxygen, and nutrition.', difficulty: 'medium' },
  { id: 'd26', topic: 'differentiation', type: 'mcq', question: 'Sclerenchymatous cells, which are dead at maturity with thick, lignified secondary walls, are formed as a result of', options: ['Dedifferentiation', 'Differentiation', 'Vernalization', 'Photoperiodism'], correctIndex: 1, explanation: 'Sclerenchyma cells acquire their characteristic thick, lignified walls through differentiation, becoming dead at maturity to provide mechanical support.', difficulty: 'medium' },
  { id: 'd27', topic: 'differentiation', type: 'mcq', question: 'Companion cells associated with sieve tube elements in phloem retain their nucleus and cytoplasm because', options: ['They never differentiate', 'Differentiation equips them with the structural features needed to support the enucleate sieve elements', 'They are a form of meristematic tissue permanently', 'They undergo redifferentiation repeatedly'], correctIndex: 1, explanation: 'Companion cells differentiate to retain a nucleus and active cytoplasm, supporting the metabolic needs of the adjacent, enucleate sieve tube elements.', difficulty: 'hard' },
  { id: 'd28', topic: 'differentiation', type: 'mcq', question: 'The concept of totipotency, where a single differentiated cell can be induced to regenerate a whole plant, relies on the plant cell\'s ability to undergo', options: ['Permanent senescence', 'Dedifferentiation followed by redifferentiation', 'Photoperiodic induction only', 'Vernalization only'], correctIndex: 1, explanation: 'Totipotency exploits the capacity of differentiated cells to dedifferentiate (regain division ability) and then redifferentiate into a complete organism.', difficulty: 'hard' },
  { id: 'd29', topic: 'differentiation', type: 'mcq', question: 'In plant tissue culture, callus formation from an explant is an example of', options: ['Redifferentiation only', 'Dedifferentiation of explant cells into an unorganised, dividing mass', 'Vernalization', 'Senescence'], correctIndex: 1, explanation: 'Callus is an unorganised, proliferating mass formed when explant cells dedifferentiate and start dividing.', difficulty: 'medium' },
  { id: 'd30', topic: 'differentiation', type: 'mcq', question: 'When shoots and roots are subsequently induced to form from a callus in tissue culture, this represents an example of', options: ['Dedifferentiation', 'Redifferentiation', 'Senescence', 'Abscission'], correctIndex: 1, explanation: 'The organised formation of shoots and roots from an undifferentiated callus mass is an example of redifferentiation.', difficulty: 'medium' },
  { id: 'd31', topic: 'differentiation', type: 'count-correct', question: 'How many of the following are examples of differentiation (not dedifferentiation)?\n(i) Formation of tracheary elements adapted for water conduction\n(ii) Formation of sclerenchyma cells with thick lignified walls\n(iii) Parenchyma cells regaining the ability to divide to form cork cambium\n(iv) Companion cells acquiring features suited to supporting sieve tubes', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements (i), (ii), and (iv) describe differentiation; statement (iii) describes dedifferentiation since it involves regaining the ability to divide.', difficulty: 'hard' },
  { id: 'd32', topic: 'differentiation', type: 'statement', question: 'Consider the following statements about plant plasticity:\n1. Plasticity allows a single genotype to produce different phenotypes in response to environment.\n2. Heterophylly in cotton and coriander is one manifestation of plasticity.\n3. Plasticity is unique to animals and absent in plants.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '2 and 3 only', '1 and 3 only', '1, 2 and 3'], correctIndex: 0, explanation: 'Statements 1 and 2 are correct; plasticity is a well-documented feature of plant development, so statement 3 is incorrect.', difficulty: 'medium' },
  { id: 'd33', topic: 'differentiation', type: 'mcq', question: 'The primary reason plants display more developmental plasticity than most animals is attributed to their', options: ['Fixed, closed form of growth', 'Open form of growth allowing modular addition of new structures throughout life', 'Complete lack of meristems', 'Inability to sense the environment'], correctIndex: 1, explanation: 'The open, indeterminate growth pattern of plants, driven by meristems, allows continuous modification of structures in response to the environment, contributing to plasticity.', difficulty: 'hard' },
  { id: 'd34', topic: 'differentiation', type: 'mcq', question: 'Formation of xylem vessels which are completely dead at maturity while sieve tubes (phloem) remain living illustrates that', options: ['Differentiation leads to structurally identical outcomes in all conducting cells', 'Differentiation produces functionally and structurally distinct cell types suited to their specific roles', 'Only phloem undergoes differentiation', 'Only xylem undergoes differentiation'], correctIndex: 1, explanation: 'The contrasting fates of xylem (dead, thick-walled) and phloem (living sieve tubes) illustrate how differentiation tailors cell structure to function.', difficulty: 'medium' },
  { id: 'd35', topic: 'differentiation', type: 'mcq', question: 'A cell that has fully differentiated and lost the capacity to divide can, under appropriate laboratory conditions, be induced to dedifferentiate. This principle underlies', options: ['Vernalization techniques', 'Plant tissue culture and micropropagation', 'Photoperiodic flower induction', 'Seed dormancy breaking'], correctIndex: 1, explanation: 'The ability of differentiated cells to dedifferentiate under suitable conditions is the biological basis for plant tissue culture techniques.', difficulty: 'medium' },
  { id: 'd36', topic: 'differentiation', type: 'mcq', question: 'Growth without differentiation is best exemplified in nature by', options: ['A fully mature leaf', 'An undifferentiated callus mass growing in culture', 'A flower', 'A woody stem'], correctIndex: 1, explanation: 'Callus tissue grows by cell division without organised differentiation, illustrating growth in the absence of differentiation.', difficulty: 'hard' },
  { id: 'd37', topic: 'differentiation', type: 'mcq', question: 'Which of the following statements about senescence is most accurate?', options: ['Senescence only affects the whole organism, never individual organs', 'Senescence is a genetically and environmentally regulated process leading to organ or organism death', 'Senescence is the same as dedifferentiation', 'Senescence cannot be influenced by hormones such as ethylene'], correctIndex: 1, explanation: 'Senescence is a regulated developmental process, influenced by genetic and environmental factors (including hormones like ethylene), ultimately leading to death of the organ/organism.', difficulty: 'medium' },
  { id: 'd38', topic: 'differentiation', type: 'assertion-reason', question: 'Assertion (A): Leaf abscission in deciduous trees before winter is considered an adaptive developmental response.\nReason (R): Abscission helps reduce water loss and prepares the plant to withstand unfavourable seasonal conditions.', options: AR_OPTIONS, correctIndex: 0, explanation: 'Reduced water loss and improved survival through unfavourable seasons directly justifies why leaf abscission is considered adaptive.', difficulty: 'medium' },
  { id: 'd39', topic: 'differentiation', type: 'mcq', question: 'Which of the following pairs correctly matches a developmental process with its outcome?', options: ['Differentiation — cells regain dividing capacity', 'Dedifferentiation — living mature cells regain dividing ability', 'Redifferentiation — cells acquire specific structure for the first time from a meristem', 'Plasticity — a fixed, unchanging developmental pathway regardless of environment'], correctIndex: 1, explanation: 'Dedifferentiation correctly describes living, mature cells regaining the ability to divide; the other options are mismatched.', difficulty: 'medium' },
  { id: 'd40', topic: 'differentiation', type: 'mcq', question: 'The overall developmental sequence in a plant, from a fertilised egg to a mature organism, is generally best described as', options: ['A random, unregulated sequence of events', 'A well-coordinated, regulated series of events involving growth, differentiation, and dedifferentiation/redifferentiation as needed', 'A process confined to the embryo alone', 'A process independent of both intrinsic and extrinsic factors'], correctIndex: 1, explanation: 'Plant development is a coordinated, tightly regulated sequence of growth and differentiation (with dedifferentiation/redifferentiation events as required), influenced by intrinsic and extrinsic factors.', difficulty: 'medium' },

// ============================================================
// SECTION 3: PLANT GROWTH REGULATORS 
// ============================================================

  // --- General PGR concepts (1-5) ---
  { id: 'h1', topic: 'hormones', type: 'mcq', question: 'Plant growth regulators (PGRs) are defined as', options: ['Enzymes that break down starch', 'Small, simple organic molecules that regulate plant growth and development', 'Large complex proteins made only by roots', 'Inorganic salts absorbed from soil'], correctIndex: 1, explanation: 'PGRs are small, simple molecules of diverse chemical composition that influence physiological processes at low concentration.', difficulty: 'easy' },
  { id: 'h2', topic: 'hormones', type: 'mcq', question: 'Based on their function, plant growth regulators can be grouped into', options: ['Growth promoters and growth inhibitors', 'Only growth promoters', 'Only inhibitors of respiration', 'Enzymes and coenzymes only'], correctIndex: 0, explanation: 'PGRs are broadly classified as growth promoters (e.g. auxins, gibberellins, cytokinins) and growth inhibitors (e.g. ABA).', difficulty: 'easy' },
  { id: 'h3', topic: 'hormones', type: 'mcq', question: 'The five major classes of naturally occurring plant growth regulators are', options: ['Auxins, gibberellins, cytokinins, ethylene, and abscisic acid', 'Insulin, glucagon, thyroxine, adrenaline, cortisol', 'Only auxins and gibberellins', 'Only ethylene and abscisic acid'], correctIndex: 0, explanation: 'The five classical groups of plant hormones are auxins, gibberellins, cytokinins, ethylene, and abscisic acid.', difficulty: 'easy' },
  { id: 'h4', topic: 'hormones', type: 'mcq', question: 'Among the five major classes of PGRs, ethylene is unique because it is the only one that is', options: ['A protein', 'A gaseous hormone', 'Found only in animals', 'Insoluble in water'], correctIndex: 1, explanation: 'Ethylene is the only major plant hormone that exists in gaseous form.', difficulty: 'easy' },
  { id: 'h5', topic: 'hormones', type: 'mcq', question: 'Which of the following is generally classified as a growth inhibitor among the plant hormones?', options: ['Auxin', 'Gibberellin', 'Abscisic acid (ABA)', 'Cytokinin'], correctIndex: 2, explanation: 'Abscisic acid is generally classified as a growth inhibitor, often antagonistic to growth-promoting hormones.', difficulty: 'easy' },

  // --- Auxin (6-23) ---
  { id: 'h6', topic: 'hormones', type: 'mcq', question: 'The classic experiments demonstrating the existence of a growth-promoting substance in the coleoptile tip of oat seedlings, leading to the discovery of auxin, were conducted by', options: ['Skoog and Miller', 'F.W. Went', 'Kurosawa', 'Lysenko'], correctIndex: 1, explanation: 'F.W. Went\'s experiments on oat coleoptiles led to the isolation and naming of auxin.', difficulty: 'medium' },
  { id: 'h7', topic: 'hormones', type: 'mcq', question: 'The first auxin to be isolated and chemically identified from human urine, later found in higher plants, is', options: ['Gibberellic acid', 'Indole-3-acetic acid (IAA)', 'Zeatin', 'Ethephon'], correctIndex: 1, explanation: 'Indole-3-acetic acid (IAA) was the first auxin isolated, and remains the most common naturally occurring auxin in plants.', difficulty: 'medium' },
  { id: 'h8', topic: 'hormones', type: 'mcq', question: 'Auxins are typically synthesised in actively growing regions of the plant such as the', options: ['Root cap only', 'Shoot and root apices, from where they migrate to the site of action', 'Mature seeds only', 'Dead xylem tissue'], correctIndex: 1, explanation: 'Auxins are synthesised chiefly in shoot and root apical tissues and then transported to other regions where needed.', difficulty: 'medium' },
  { id: 'h9', topic: 'hormones', type: 'mcq', question: 'Auxins primarily promote', options: ['Only leaf senescence', 'Cell elongation, particularly in shoots', 'Fruit ripening only', 'Stomatal closure'], correctIndex: 1, explanation: 'A major and well-known function of auxin is promoting cell elongation, particularly in shoot tissues.', difficulty: 'easy' },
  { id: 'h10', topic: 'hormones', type: 'mcq', question: 'Auxin brings about phototropic bending of a shoot towards light through the mechanism explained by the', options: ['Cholodny-Went theory', 'Central dogma', 'Munch hypothesis', 'Law of limiting factors'], correctIndex: 0, explanation: 'The Cholodny-Went theory explains phototropism as due to asymmetric distribution of auxin, promoting greater elongation on the shaded side.', difficulty: 'hard' },
  { id: 'h11', topic: 'hormones', type: 'mcq', question: 'The suppression of growth of lateral (axillary) buds by the growing apical shoot bud, which can be relieved by removing the apex, is termed', options: ['Vernalization', 'Apical dominance', 'Photoperiodism', 'Abscission'], correctIndex: 1, explanation: 'Apical dominance, mediated largely by auxin from the apical bud, suppresses growth of lateral buds; removing the apex releases lateral buds from this inhibition.', difficulty: 'medium' },
  { id: 'h12', topic: 'hormones', type: 'mcq', question: 'Gardeners and farmers often remove the shoot apex (a practice called decapitation) in hedge plants and tea bushes to', options: ['Increase apical dominance', 'Promote a bushy appearance by releasing lateral buds from apical dominance', 'Delay flowering', 'Reduce the number of leaves'], correctIndex: 1, explanation: 'Removing the apical bud releases lateral buds from apical dominance, resulting in more branching and a bushy appearance — used in tea plantations and hedge-making.', difficulty: 'medium' },
  { id: 'h13', topic: 'hormones', type: 'mcq', question: 'Auxins promote the initiation of', options: ['Only leaf abscission', 'Rooting in stem cuttings, useful for plant propagation', 'Seed dormancy only', 'Chlorophyll breakdown'], correctIndex: 1, explanation: 'Auxin application is widely used in horticulture to promote rooting in stem cuttings for vegetative propagation.', difficulty: 'medium' },
  { id: 'h14', topic: 'hormones', type: 'mcq', question: 'Auxins are commonly used commercially to induce the development of seedless fruits, a phenomenon known as', options: ['Vernalization', 'Parthenocarpy', 'Photoperiodism', 'Vivipary'], correctIndex: 1, explanation: 'Auxin can induce parthenocarpic (seedless) fruit development in some plants like tomatoes, without the need for fertilisation.', difficulty: 'medium' },
  { id: 'h15', topic: 'hormones', type: 'mcq', question: 'Application of auxin prevents premature drop of', options: ['Roots', 'Fruits and leaves', 'Stems', 'Pollen grains'], correctIndex: 1, explanation: 'Auxin helps prevent premature fruit and leaf abscission (drop) in some plants when applied appropriately.', difficulty: 'medium' },
  { id: 'h16', topic: 'hormones', type: 'mcq', question: 'Synthetic auxins such as 2,4-D (2,4-dichlorophenoxyacetic acid) are widely used commercially as', options: ['Fungicides', 'Weedicides/herbicides, particularly to kill dicot weeds', 'Insecticides', 'Fertilisers'], correctIndex: 1, explanation: '2,4-D is a synthetic auxin extensively used as a herbicide, particularly to control dicotyledonous weeds in monocot crop fields.', difficulty: 'medium' },
  { id: 'h17', topic: 'hormones', type: 'assertion-reason', question: 'Assertion (A): 2,4-D is used to kill dicot weeds growing in monocot crop fields without harming the crop.\nReason (R): Auxins like 2,4-D affect dicots differently from monocots, and does not affect grasses at effective herbicidal concentrations.', options: AR_OPTIONS, correctIndex: 0, explanation: 'The differential sensitivity of dicots to synthetic auxin herbicides like 2,4-D, while sparing monocot grasses, directly explains its selective weedicidal use.', difficulty: 'medium' },
  { id: 'h18', topic: 'hormones', type: 'mcq', question: 'In plant tissue culture, a high auxin to cytokinin ratio in the medium generally promotes', options: ['Shoot formation', 'Root formation', 'Flower formation only', 'No growth at all'], correctIndex: 1, explanation: 'A high auxin:cytokinin ratio tends to favour root formation, whereas a high cytokinin:auxin ratio favours shoot formation in tissue culture.', difficulty: 'hard' },
  { id: 'h19', topic: 'hormones', type: 'mcq', question: 'Auxin plays a role in the differentiation of', options: ['Only leaf epidermis', 'Xylem and phloem tissue', 'Root cap alone', 'Only guard cells'], correctIndex: 1, explanation: 'Auxin, often in coordination with other hormones, influences the differentiation of vascular tissues (xylem and phloem).', difficulty: 'medium' },
  { id: 'h20', topic: 'hormones', type: 'mcq', question: 'Which of the following is NOT a typical physiological effect of auxin?', options: ['Promoting cell elongation', 'Inducing apical dominance', 'Inducing parthenocarpy', 'Promoting stomatal closure under water stress'], correctIndex: 3, explanation: 'Stomatal closure under water stress is chiefly mediated by abscisic acid (ABA), not auxin.', difficulty: 'medium' },
  { id: 'h21', topic: 'hormones', type: 'matching', question: 'Match the auxin-related effect in Column I with its application/example in Column II.\nColumn I: A. Apical dominance, B. Parthenocarpy, C. Weedicide use, D. Rooting of cuttings\nColumn II: (i) Seedless tomato development, (ii) 2,4-D against dicot weeds, (iii) Growth of lateral bud suppressed by apex, (iv) IAA/IBA used in horticulture', options: ['A-iii, B-i, C-ii, D-iv', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-i, D-ii', 'A-iii, B-iv, C-ii, D-i'], correctIndex: 0, explanation: 'Apical dominance = suppression of lateral bud; parthenocarpy = seedless fruit; weedicide = 2,4-D; rooting = IAA/IBA application.', difficulty: 'medium' },
  { id: 'h22', topic: 'hormones', type: 'statement', question: 'Consider the following statements about auxin:\n1. IAA is a naturally occurring auxin.\n2. Auxins are typically synthesised in mature, senescent leaves.\n3. Auxins can promote rooting in stem cuttings.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '1 and 3 only', '2 and 3 only', '1, 2 and 3'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct; auxins are chiefly synthesised in actively growing regions (apices), not senescent leaves, so statement 2 is incorrect.', difficulty: 'medium' },
  { id: 'h23', topic: 'hormones', type: 'count-correct', question: 'How many of the following are recognised physiological effects of auxins?\n(i) Promotion of cell elongation\n(ii) Induction of apical dominance\n(iii) Induction of parthenocarpy\n(iv) Promotion of stomatal closure\n(v) Prevention of premature leaf/fruit drop', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 2, explanation: 'Cell elongation, apical dominance, parthenocarpy, and prevention of premature drop are auxin effects; stomatal closure is primarily an ABA effect.', difficulty: 'hard' },

  // --- Gibberellins (24-39) ---
  { id: 'h24', topic: 'hormones', type: 'mcq', question: 'Gibberellins were first discovered in connection with a disease of rice plants called', options: ['Bakanae or "foolish seedling" disease', 'Rice blast', 'Leaf curl disease', 'Rust disease'], correctIndex: 0, explanation: 'Gibberellins were discovered through studies of bakanae disease in rice, caused by the fungus Gibberella fujikuroi.', difficulty: 'medium' },
  { id: 'h25', topic: 'hormones', type: 'mcq', question: 'The fungus associated with the discovery of gibberellins, causing abnormally tall and spindly rice seedlings, is', options: ['Gibberella fujikuroi', 'Agrobacterium tumefaciens', 'Rhizobium', 'Puccinia graminis'], correctIndex: 0, explanation: 'Gibberella fujikuroi is the fungus that produces gibberellin, causing excessive elongation (bakanae disease) in infected rice seedlings.', difficulty: 'medium' },
  { id: 'h26', topic: 'hormones', type: 'mcq', question: 'The most extensively studied and commonly used gibberellin, first isolated and named, is', options: ['GA3 (gibberellic acid)', 'IAA', 'Kinetin', 'Zeatin'], correctIndex: 0, explanation: 'GA3, or gibberellic acid, is the most studied gibberellin and among the most commonly used in research and agriculture.', difficulty: 'medium' },
  { id: 'h27', topic: 'hormones', type: 'mcq', question: 'A characteristic and easily observable effect of gibberellins on intact plants is', options: ['Causing dwarfism', 'Causing an increase in the length of the axis (elongation of the plant)', 'Preventing seed germination', 'Preventing fruit set'], correctIndex: 1, explanation: 'Gibberellins are well known for causing elongation of the plant axis, in contrast to conditions like genetic dwarfism.', difficulty: 'easy' },
  { id: 'h28', topic: 'hormones', type: 'mcq', question: 'Gibberellins can cause "bolting" — rapid elongation of the floral stalk before flowering — in rosette plants like', options: ['Cabbage', 'Wheat', 'Maize', 'Sugarcane'], correctIndex: 0, explanation: 'Gibberellins induce bolting, the rapid elongation of the stem axis before flowering, in rosette plants such as cabbage.', difficulty: 'medium' },
  { id: 'h29', topic: 'hormones', type: 'mcq', question: 'Gibberellins are extensively used in the brewing industry, particularly in the process of', options: ['Malting of barley seeds', 'Fermentation of wine grapes only', 'Distillation of spirits', 'Roasting of coffee'], correctIndex: 0, explanation: 'GA is used industrially to speed up the malting process in barley by hastening amylase production for germination.', difficulty: 'medium' },
  { id: 'h30', topic: 'hormones', type: 'mcq', question: 'Gibberellins promote seed germination in some seeds by stimulating the production of', options: ['Chlorophyll', 'Alpha-amylase, which mobilises stored starch', 'Cellulose in cell walls', 'Melanin'], correctIndex: 1, explanation: 'GA induces the synthesis of alpha-amylase in germinating cereal seeds, breaking down starch into usable sugars.', difficulty: 'medium' },
  { id: 'h31', topic: 'hormones', type: 'mcq', question: 'Gibberellins can help increase the size of fruits like grapes and hasten maturity in fruits such as', options: ['Apples only', 'Grapes and apples in commercial horticulture', 'Only rice grains', 'Only wheat grains'], correctIndex: 1, explanation: 'GA application is used commercially to increase fruit size in grapes and hasten maturity in apples.', difficulty: 'medium' },
  { id: 'h32', topic: 'hormones', type: 'mcq', question: 'Gibberellins can also induce parthenocarpic fruit development in plants such as', options: ['Apple and pear', 'Wheat and rice only', 'Cabbage only', 'Onion only'], correctIndex: 0, explanation: 'GA has been used to induce parthenocarpic (seedless) fruit development in plants like apple and pear.', difficulty: 'medium' },
  { id: 'h33', topic: 'hormones', type: 'mcq', question: 'Gibberellins can delay senescence in fruits, which is useful for', options: ['Reducing sugar content', 'Extending storage/transport time of citrus fruits', 'Speeding up ripening', 'Promoting flower drop'], correctIndex: 1, explanation: 'GA can delay senescence in fruits, useful for extending the transport period of citrus fruits.', difficulty: 'medium' },
  { id: 'h34', topic: 'hormones', type: 'mcq', question: 'GA can induce flowering in long-day plants when they are maintained under short days, and can also promote flowering in', options: ['Only short-day plants', 'Biennial plants without requiring the cold treatment they normally need', 'Day-neutral plants only', 'Plants that never flower'], correctIndex: 1, explanation: 'GA can substitute for the cold requirement in biennials and can also induce flowering in long-day plants kept under short days.', difficulty: 'hard' },
  { id: 'h35', topic: 'hormones', type: 'assertion-reason', question: 'Assertion (A): Gibberellins are useful in increasing the length of grapes.\nReason (R): GA is well known to promote elongation of the plant axis and internodes.', options: AR_OPTIONS, correctIndex: 0, explanation: 'The known elongation-promoting effect of GA directly explains its commercial use in increasing grape length, correctly supporting the assertion.', difficulty: 'medium' },
  { id: 'h36', topic: 'hormones', type: 'mcq', question: 'A key structural feature shared by all gibberellins is that they are', options: ['Steroid hormones', 'Acidic in nature, based on a gibbane ring skeleton', 'Basic, alkaline compounds', 'Gaseous compounds'], correctIndex: 1, explanation: 'Gibberellins are acidic compounds, structurally based on a gibbane ring skeleton.', difficulty: 'hard' },
  { id: 'h37', topic: 'hormones', type: 'statement', question: 'Consider the following statements about gibberellins:\n1. GA was first discovered from a fungus causing disease in rice.\n2. GA typically causes dwarfing in treated plants.\n3. GA can induce bolting in rosette plants.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '1 and 3 only', '2 and 3 only', '1, 2 and 3'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct; GA promotes elongation rather than dwarfing, so statement 2 is incorrect.', difficulty: 'medium' },
  { id: 'h38', topic: 'hormones', type: 'count-correct', question: 'How many of the following are true effects of gibberellins?\n(i) Bolting in rosette plants\n(ii) Increase in fruit size\n(iii) Stimulation of alpha-amylase during seed germination\n(iv) Induction of stomatal closure under water stress\n(v) Delaying senescence of fruits', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 3, explanation: 'Bolting, fruit size increase, amylase stimulation, and delayed senescence are all gibberellin effects; stomatal closure under stress is mainly an ABA-mediated response.', difficulty: 'hard' },
  { id: 'h39', topic: 'hormones', type: 'mcq', question: 'Compared to auxin, gibberellins are chiefly distinguished by their prominent role in', options: ['Root initiation from cuttings', 'Stem elongation, bolting, and seed germination', 'Fruit ripening exclusively', 'Stomatal closure'], correctIndex: 1, explanation: 'While auxin is closely linked to rooting and apical dominance, gibberellins are especially known for stem elongation, bolting, and seed germination effects.', difficulty: 'medium' },

  // --- Cytokinins (40-53) ---
  { id: 'h40', topic: 'hormones', type: 'mcq', question: 'Cytokinins were discovered while studying substances that could induce', options: ['Root formation exclusively', 'Cell division (cytokinesis) in cultured plant tissues', 'Stomatal closure', 'Seed dormancy'], correctIndex: 1, explanation: 'Cytokinins were discovered as substances promoting cell division (cytokinesis) in cultured cells.', difficulty: 'medium' },
  { id: 'h41', topic: 'hormones', type: 'mcq', question: 'The first cytokinin, kinetin, was isolated from', options: ['Coconut milk', 'Autoclaved herring sperm DNA', 'Fungal cultures of Gibberella', 'Barley grains'], correctIndex: 1, explanation: 'Kinetin, the first identified cytokinin, was obtained from autoclaved herring sperm DNA — it does not occur naturally in plants.', difficulty: 'medium' },
  { id: 'h42', topic: 'hormones', type: 'mcq', question: 'A naturally occurring cytokinin, isolated from corn kernels and coconut milk, is', options: ['Zeatin', 'Kinetin', 'GA3', 'IBA'], correctIndex: 0, explanation: 'Zeatin is a naturally occurring cytokinin, isolated from corn (Zea mays) kernels and also present in coconut milk.', difficulty: 'medium' },
  { id: 'h43', topic: 'hormones', type: 'mcq', question: 'Cytokinins are chiefly produced in plant regions undergoing rapid cell division, such as', options: ['Root apices, developing shoot buds, young fruits, and seeds', 'Only mature xylem', 'Only fully senescent leaves', 'Only dead cork tissue'], correctIndex: 0, explanation: 'Cytokinins are synthesised mainly in regions of rapid cell division, including root apices, shoot buds, and developing seeds/fruits.', difficulty: 'medium' },
  { id: 'h44', topic: 'hormones', type: 'mcq', question: 'Cytokinins are especially important in helping to overcome', options: ['Seed dormancy exclusively', 'Apical dominance, promoting lateral bud growth', 'Fruit ripening', 'Stomatal opening'], correctIndex: 1, explanation: 'Cytokinins help overcome apical dominance, promoting the growth of lateral buds by counteracting auxin\'s suppressive effect.', difficulty: 'medium' },
  { id: 'h45', topic: 'hormones', type: 'mcq', question: 'Cytokinins delay the process of leaf senescence, a phenomenon known as the', options: ['Went effect', 'Richmond-Lang effect', 'Cholodny effect', 'Bolting effect'], correctIndex: 1, explanation: 'The delaying effect of cytokinins on leaf senescence is termed the Richmond-Lang effect.', difficulty: 'hard' },
  { id: 'h46', topic: 'hormones', type: 'mcq', question: 'Cytokinins help promote the movement of nutrients within a plant towards the tissue where they are applied, a phenomenon called', options: ['Photoperiodism', 'Nutrient mobilisation', 'Photorespiration', 'Osmosis'], correctIndex: 1, explanation: 'Cytokinins can trigger nutrient mobilisation, drawing nutrients towards the tissue where they are applied.', difficulty: 'medium' },
  { id: 'h47', topic: 'hormones', type: 'mcq', question: 'In plant tissue culture media, a high cytokinin to auxin ratio typically induces', options: ['Root formation', 'Shoot bud formation', 'Callus death', 'Prevention of any growth'], correctIndex: 1, explanation: 'A relatively high cytokinin:auxin ratio favours shoot formation, complementing the role of a high auxin:cytokinin ratio in root formation.', difficulty: 'hard' },
  { id: 'h48', topic: 'hormones', type: 'mcq', question: 'Cytokinins help promote which of the following in plant growth?', options: ['Cell division and differentiation', 'Only stomatal closure', 'Only fruit ripening', 'Only ethylene production'], correctIndex: 0, explanation: 'A primary role of cytokinins is stimulating cell division, along with morphogenesis (differentiation) in tissues.', difficulty: 'easy' },
  { id: 'h49', topic: 'hormones', type: 'assertion-reason', question: 'Assertion (A): Application of cytokinin to a detached leaf delays its yellowing (senescence).\nReason (R): Cytokinins promote protein synthesis and delay chlorophyll breakdown in leaf tissue.', options: AR_OPTIONS, correctIndex: 0, explanation: 'Cytokinin\'s role in maintaining protein synthesis and delaying chlorophyll degradation directly explains its senescence-delaying (Richmond-Lang) effect.', difficulty: 'hard' },
  { id: 'h50', topic: 'hormones', type: 'mcq', question: 'Kinetin, though not naturally found in plants, is often used experimentally because it', options: ['Mimics the effects of naturally occurring cytokinins like zeatin', 'Behaves like an auxin', 'Behaves like ethylene', 'Is a growth inhibitor'], correctIndex: 0, explanation: 'Kinetin is used experimentally as a synthetic cytokinin that mimics the physiological effects of natural cytokinins such as zeatin.', difficulty: 'medium' },
  { id: 'h51', topic: 'hormones', type: 'matching', question: 'Match the cytokinin-related term in Column I with its description in Column II.\nColumn I: A. Kinetin, B. Zeatin, C. Richmond-Lang effect\nColumn II: (i) Delay of leaf senescence by cytokinin, (ii) Synthetic cytokinin from herring sperm DNA, (iii) Natural cytokinin from corn and coconut milk', options: ['A-ii, B-iii, C-i', 'A-i, B-ii, C-iii', 'A-iii, B-i, C-ii', 'A-ii, B-i, C-iii'], correctIndex: 0, explanation: 'Kinetin = synthetic cytokinin from herring sperm DNA; zeatin = natural cytokinin from corn/coconut milk; Richmond-Lang effect = delay of senescence.', difficulty: 'medium' },
  { id: 'h52', topic: 'hormones', type: 'statement', question: 'Consider the following statements about cytokinins:\n1. Cytokinins promote cell division.\n2. Cytokinins accelerate leaf senescence.\n3. Cytokinins help overcome apical dominance.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '1 and 3 only', '2 and 3 only', '1, 2 and 3'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct; cytokinins delay, not accelerate, leaf senescence, so statement 2 is incorrect.', difficulty: 'medium' },
  { id: 'h53', topic: 'hormones', type: 'count-correct', question: 'How many of the following are true effects of cytokinins?\n(i) Promotion of cell division\n(ii) Delay of leaf senescence\n(iii) Overcoming apical dominance\n(iv) Inducing seed dormancy\n(v) Promoting nutrient mobilisation towards application site', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 3, explanation: 'Cell division promotion, senescence delay, overcoming apical dominance, and nutrient mobilisation are true cytokinin effects; inducing seed dormancy is instead a role of ABA.', difficulty: 'hard' },

  // --- Ethylene (54-67) ---
  { id: 'h54', topic: 'hormones', type: 'mcq', question: 'Among the classical plant hormones, the one that exists as a simple gaseous hydrocarbon is', options: ['Auxin', 'Ethylene', 'Cytokinin', 'ABA'], correctIndex: 1, explanation: 'Ethylene (C2H4) is a simple, gaseous hydrocarbon and the only classical plant hormone existing in this state.', difficulty: 'easy' },
  { id: 'h55', topic: 'hormones', type: 'mcq', question: 'Ethylene\'s most widely recognised and commercially exploited effect is on', options: ['Root elongation', 'Fruit ripening', 'Seed dormancy induction', 'Photosynthesis rate'], correctIndex: 1, explanation: 'Ethylene is best known for its role in triggering and coordinating fruit ripening.', difficulty: 'easy' },
  { id: 'h56', topic: 'hormones', type: 'mcq', question: 'Ethylene is particularly effective in initiating', options: ['Germination of most non-dormant seeds', 'Breaking dormancy of seeds and buds', 'Photosynthesis directly', 'Chlorophyll synthesis'], correctIndex: 1, explanation: 'Ethylene can help break dormancy in seeds and buds, initiating germination or sprouting.', difficulty: 'medium' },
  { id: 'h57', topic: 'hormones', type: 'mcq', question: 'Ethylene promotes rapid internode/petiole elongation in deep water rice plants, illustrating its role in', options: ['Preventing any growth response to flooding', 'Helping the plant escape submergence', 'Slowing seed germination', 'Increasing root branching only'], correctIndex: 1, explanation: 'In deep water rice, ethylene accumulation under flooding triggers rapid elongation, helping leaves reach above the water surface.', difficulty: 'hard' },
  { id: 'h58', topic: 'hormones', type: 'mcq', question: 'Ethylene promotes senescence and abscission of', options: ['Only roots', 'Leaves and flowers', 'Only stems', 'Only seeds'], correctIndex: 1, explanation: 'Ethylene is a key hormone promoting senescence and abscission of plant organs such as leaves and flowers.', difficulty: 'medium' },
  { id: 'h59', topic: 'hormones', type: 'mcq', question: 'Ethylene enhances the rate of ripening of fruits and is used commercially by fruit farmers to hasten ripening of', options: ['Tomato and apple', 'Only unripe grains', 'Only fully ripe fruits', 'Only flowers'], correctIndex: 0, explanation: 'Ethylene is commonly used to hasten ripening in commercially important fruits such as tomatoes and apples.', difficulty: 'medium' },
  { id: 'h60', topic: 'hormones', type: 'mcq', question: 'The synthetic compound ethephon, when sprayed on plants, releases ethylene and is used commercially to', options: ['Hasten fruit ripening and induce flowering in some plants like mango', 'Delay flowering permanently', 'Prevent all growth', 'Induce dormancy'], correctIndex: 0, explanation: 'Ethephon, a source of ethylene when applied, is used to hasten fruit ripening and induce flowering (e.g., in pineapple and mango).', difficulty: 'medium' },
  { id: 'h61', topic: 'hormones', type: 'mcq', question: 'Ethylene is closely associated with the "triple response" observed in dark-grown seedlings, which involves', options: ['Reduction in stem elongation, increase in stem thickening, and horizontal (diagravitropic) growth', 'Only increased flowering', 'Only root elongation', 'Only chlorophyll formation'], correctIndex: 0, explanation: 'The triple response — reduced elongation, increased radial swelling, and horizontal growth — is a classic bioassay for ethylene action.', difficulty: 'hard' },
  { id: 'h62', topic: 'hormones', type: 'mcq', question: 'Ethylene promotes the growth response known as epinasty, in which', options: ['Roots grow toward gravity', 'The upper side of a leaf/petiole grows faster than the lower side, causing downward curving', 'Leaves curl upward only', 'Stems grow horizontally without curving'], correctIndex: 1, explanation: 'Epinasty, promoted by ethylene, involves faster growth of the upper petiole surface, causing the leaf to bend downward.', difficulty: 'hard' },
  { id: 'h63', topic: 'hormones', type: 'mcq', question: 'Ethylene is synthesised in plants from the amino acid', options: ['Tryptophan', 'Methionine', 'Glycine', 'Lysine'], correctIndex: 1, explanation: 'Ethylene biosynthesis in plants occurs from the amino acid methionine.', difficulty: 'hard' },
  { id: 'h64', topic: 'hormones', type: 'assertion-reason', question: 'Assertion (A): Ethylene is used commercially to induce flowering and synchronise fruit-set in pineapples.\nReason (R): Ethylene can induce flowering in certain plants and is applied commercially for this purpose.', options: AR_OPTIONS, correctIndex: 0, explanation: 'Ethylene\'s known ability to induce flowering directly explains its commercial use in synchronising pineapple flowering and fruiting.', difficulty: 'medium' },
  { id: 'h65', topic: 'hormones', type: 'mcq', question: 'Which of the following is NOT typically a recognised effect of ethylene?', options: ['Fruit ripening', 'Leaf and flower senescence/abscission', 'Breaking of seed/bud dormancy', 'Prevention of all senescence indefinitely'], correctIndex: 3, explanation: 'Ethylene actually promotes, rather than prevents, senescence; it is not associated with indefinite prevention of senescence.', difficulty: 'medium' },
  { id: 'h66', topic: 'hormones', type: 'statement', question: 'Consider the following statements about ethylene:\n1. It is the only gaseous hormone among the classical plant hormones.\n2. It delays fruit ripening.\n3. It promotes the triple response in etiolated seedlings.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '1 and 3 only', '2 and 3 only', '1, 2 and 3'], correctIndex: 1, explanation: 'Statements 1 and 3 are correct; ethylene promotes (not delays) fruit ripening, so statement 2 is incorrect.', difficulty: 'medium' },
  { id: 'h67', topic: 'hormones', type: 'count-correct', question: 'How many of the following are correct statements about ethylene?\n(i) It is used to speed up fruit ripening commercially.\n(ii) It promotes epinasty of leaves.\n(iii) It promotes stomatal closure primarily under water stress.\n(iv) It can help plants adapt to flooding by promoting elongation.', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements (i), (ii), and (iv) are true ethylene effects; stomatal closure under water stress is chiefly mediated by ABA, not ethylene.', difficulty: 'hard' },

  // --- Abscisic acid (68-80) ---
  { id: 'h68', topic: 'hormones', type: 'mcq', question: 'Abscisic acid (ABA) is often described as a general growth inhibitor and is associated with plant responses to', options: ['Favourable growth conditions only', 'Stress conditions such as drought', 'Only flowering time control', 'Only fruit ripening'], correctIndex: 1, explanation: 'ABA is well-known as the "stress hormone," playing a key role in helping plants withstand adverse conditions like drought.', difficulty: 'easy' },
  { id: 'h69', topic: 'hormones', type: 'mcq', question: 'ABA plays a critical role in inducing', options: ['Rapid seed germination', 'Seed dormancy, preventing precocious germination', 'Fruit ripening acceleration', 'Bolting in rosette plants'], correctIndex: 1, explanation: 'ABA induces and maintains seed dormancy, preventing seeds from germinating prematurely under unfavourable conditions.', difficulty: 'medium' },
  { id: 'h70', topic: 'hormones', type: 'mcq', question: 'A well-known and rapid physiological effect of ABA under water-deficit (drought) conditions is', options: ['Opening of stomata', 'Closure of stomata to reduce transpirational water loss', 'Increased root branching immediately', 'Increased leaf expansion'], correctIndex: 1, explanation: 'ABA induces stomatal closure during water stress, helping the plant conserve water.', difficulty: 'easy' },
  { id: 'h71', topic: 'hormones', type: 'mcq', question: 'Because ABA counteracts the growth-promoting effects of gibberellins, it is often referred to as an', options: ['Antitranspirant hormone alone', 'Antagonist of gibberellins', 'Auxin analogue', 'Ethylene precursor'], correctIndex: 1, explanation: 'ABA is frequently described as a physiological antagonist of gibberellins due to its opposing effects on many processes, including dormancy.', difficulty: 'medium' },
  { id: 'h72', topic: 'hormones', type: 'mcq', question: 'ABA is also referred to as the "stress hormone" because it helps the plant adapt to conditions of', options: ['Excess sunlight only', 'Water stress and other environmental stresses', 'Excess fertiliser only', 'Only cold-free environments'], correctIndex: 1, explanation: 'ABA plays a central role in helping plants cope with environmental stresses, especially water stress, earning it the name "stress hormone."', difficulty: 'easy' },
  { id: 'h73', topic: 'hormones', type: 'mcq', question: 'Increased ABA levels in a leaf under drought conditions typically lead to', options: ['Enhanced transpiration', 'Reduced water loss via stomatal closure', 'Increased chlorophyll synthesis', 'Increased seed germination'], correctIndex: 1, explanation: 'ABA-triggered stomatal closure reduces transpirational water loss, an important drought-response mechanism.', difficulty: 'medium' },
  { id: 'h74', topic: 'hormones', type: 'mcq', question: 'ABA can inhibit which of the following processes in seeds?', options: ['Dormancy establishment', 'Seed germination', 'Photosynthesis in mature leaves', 'Nitrogen fixation'], correctIndex: 1, explanation: 'ABA is well-documented for its inhibitory effect on seed germination, complementing its role in maintaining dormancy.', difficulty: 'medium' },
  { id: 'h75', topic: 'hormones', type: 'assertion-reason', question: 'Assertion (A): ABA is called an inhibitory hormone.\nReason (R): ABA inhibits seed germination, growth, and induces stomatal closure, acting in opposition to several growth promoters like GA.', options: AR_OPTIONS, correctIndex: 0, explanation: 'ABA\'s inhibitory action on germination, growth, and its stomatal-closing effect directly justify its classification as an inhibitory hormone.', difficulty: 'medium' },
  { id: 'h76', topic: 'hormones', type: 'mcq', question: 'ABA is synthesised in various plant parts, but is particularly associated with production in', options: ['Only pollen grains', 'Leaves, especially under water stress conditions', 'Only germinated seeds', 'Only ripe fruits'], correctIndex: 1, explanation: 'ABA is synthesised in various tissues but shows a marked increase in leaves during periods of water stress.', difficulty: 'medium' },
  { id: 'h77', topic: 'hormones', type: 'mcq', question: 'Which of the following processes is generally promoted, not inhibited, by ABA?', options: ['Seed germination', 'Stomatal opening', 'Bud dormancy and desiccation tolerance', 'Cell division at the shoot apex'], correctIndex: 2, explanation: 'ABA promotes bud dormancy and helps confer desiccation tolerance, unlike the other listed processes which it typically inhibits.', difficulty: 'medium' },
  { id: 'h78', topic: 'hormones', type: 'statement', question: 'Consider the following statements about abscisic acid (ABA):\n1. ABA is a growth-promoting hormone like auxin.\n2. ABA induces stomatal closure during water stress.\n3. ABA plays a role in seed dormancy.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '2 and 3 only', '1 and 3 only', '1, 2 and 3'], correctIndex: 1, explanation: 'Statements 2 and 3 are correct; ABA is a growth inhibitor, not a promoter, so statement 1 is incorrect.', difficulty: 'medium' },
  { id: 'h79', topic: 'hormones', type: 'count-correct', question: 'How many of the following are true effects of abscisic acid (ABA)?\n(i) Inducing seed dormancy\n(ii) Promoting stomatal closure\n(iii) Promoting bud dormancy\n(iv) Accelerating fruit ripening\n(v) Inhibiting seed germination', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 3, explanation: 'Seed dormancy induction, stomatal closure, bud dormancy, and germination inhibition are true ABA effects; fruit ripening is primarily driven by ethylene, not ABA.', difficulty: 'hard' },
  { id: 'h80', topic: 'hormones', type: 'matching', question: 'Match the plant hormone in Column I with its most characteristic effect in Column II.\nColumn I: A. Auxin, B. Gibberellin, C. Cytokinin, D. Ethylene, E. ABA\nColumn II: (i) Fruit ripening, (ii) Stomatal closure under stress, (iii) Apical dominance, (iv) Delay of leaf senescence, (v) Bolting in rosette plants', options: ['A-iii, B-v, C-iv, D-i, E-ii', 'A-i, B-ii, C-iii, D-iv, E-v', 'A-v, B-iii, C-ii, D-i, E-iv', 'A-iii, B-i, C-v, D-ii, E-iv'], correctIndex: 0, explanation: 'Auxin = apical dominance; gibberellin = bolting; cytokinin = delays senescence; ethylene = fruit ripening; ABA = stomatal closure under stress.', difficulty: 'medium' },

// ============================================================
// SECTION 4: PHOTOPERIODISM AND VERNALIZATION 
// ============================================================

  { id: 'p1', topic: 'photoperiodism', type: 'mcq', question: 'Photoperiodism refers to the response of plants to', options: ['Soil pH', 'The relative length of day and night (photoperiod)', 'Wind speed', 'Atmospheric CO2 concentration alone'], correctIndex: 1, explanation: 'Photoperiodism is the physiological response of plants to the relative lengths of day and night.', difficulty: 'easy' },
  { id: 'p2', topic: 'photoperiodism', type: 'mcq', question: 'Photoperiodism was first discovered and characterised through experiments on', options: ['Wheat and its vernalization requirement', 'Tobacco and soybean plants by Garner and Allard', 'Barley malting', 'Coconut cytokinin extraction'], correctIndex: 1, explanation: 'Garner and Allard first described photoperiodism through their studies on tobacco and soybean flowering responses.', difficulty: 'medium' },
  { id: 'p3', topic: 'photoperiodism', type: 'mcq', question: 'Photoperiodism is particularly important in regulating which developmental process in many plants?', options: ['Root branching', 'Flowering (transition to reproductive phase)', 'Seed coat formation', 'Cork formation'], correctIndex: 1, explanation: 'Photoperiodism most notably regulates flowering time in a wide range of plant species.', difficulty: 'easy' },
  { id: 'p4', topic: 'photoperiodism', type: 'mcq', question: 'Plants that flower only when exposed to a photoperiod shorter than a certain critical duration are called', options: ['Long-day plants', 'Short-day plants', 'Day-neutral plants', 'Photoperiod-insensitive plants'], correctIndex: 1, explanation: 'Short-day plants require a photoperiod shorter than a critical length to induce flowering.', difficulty: 'easy' },
  { id: 'p5', topic: 'photoperiodism', type: 'mcq', question: 'Plants that flower only when the photoperiod exceeds a critical duration are called', options: ['Short-day plants', 'Long-day plants', 'Day-neutral plants', 'Aseasonal plants'], correctIndex: 1, explanation: 'Long-day plants require a photoperiod longer than a critical value to flower.', difficulty: 'easy' },
  { id: 'p6', topic: 'photoperiodism', type: 'mcq', question: 'Plants whose flowering is not dependent on the photoperiod they receive are called', options: ['Short-day plants', 'Long-day plants', 'Day-neutral plants', 'Vernalization-dependent plants'], correctIndex: 2, explanation: 'Day-neutral plants flower regardless of photoperiod, such as tomato and cotton.', difficulty: 'easy' },
  { id: 'p7', topic: 'photoperiodism', type: 'mcq', question: 'Chrysanthemum and tobacco are classic examples of', options: ['Long-day plants', 'Short-day plants', 'Day-neutral plants', 'Vernalization-obligate plants'], correctIndex: 1, explanation: 'Chrysanthemum and tobacco are classic examples of short-day plants that require photoperiods shorter than a critical length to flower.', difficulty: 'medium' },
  { id: 'p8', topic: 'photoperiodism', type: 'mcq', question: 'Spinach and radish are commonly cited examples of', options: ['Short-day plants', 'Long-day plants', 'Day-neutral plants', 'Non-flowering plants'], correctIndex: 1, explanation: 'Spinach and radish are examples of long-day plants that flower when the photoperiod exceeds the critical length.', difficulty: 'medium' },
  { id: 'p9', topic: 'photoperiodism', type: 'mcq', question: 'Tomato and cotton are commonly cited examples of', options: ['Short-day plants', 'Long-day plants', 'Day-neutral plants', 'Obligate short-day plants'], correctIndex: 2, explanation: 'Tomato and cotton flower irrespective of the photoperiod, making them day-neutral plants.', difficulty: 'medium' },
  { id: 'p10', topic: 'photoperiodism', type: 'mcq', question: 'The site of perception of the photoperiodic stimulus in plants is primarily the', options: ['Root tip', 'Leaf', 'Flower bud itself', 'Fruit'], correctIndex: 1, explanation: 'The leaf is the site where the photoperiodic stimulus is perceived, even though the response (flowering) occurs at the shoot apex.', difficulty: 'medium' },
  { id: 'p11', topic: 'photoperiodism', type: 'mcq', question: 'The pigment primarily involved in perception of the photoperiodic signal in plants is', options: ['Chlorophyll a', 'Phytochrome', 'Xanthophyll', 'Anthocyanin'], correctIndex: 1, explanation: 'Phytochrome is the photoreceptor pigment chiefly responsible for perceiving photoperiodic signals related to flowering.', difficulty: 'medium' },
  { id: 'p12', topic: 'photoperiodism', type: 'mcq', question: 'For obligate short-day plants, flowering is actually more precisely determined by', options: ['Exact day length alone, with no relevance to night length', 'The length of the continuous dark period (night), not just day length', 'Total rainfall', 'Only soil temperature'], correctIndex: 1, explanation: 'It has been established that flowering in short-day plants is more critically dependent on an uninterrupted length of darkness (night) than on day length itself.', difficulty: 'hard' },
  { id: 'p13', topic: 'photoperiodism', type: 'assertion-reason', question: 'Assertion (A): A short-day plant can be prevented from flowering by interrupting its long dark period with a brief flash of light.\nReason (R): The critical factor governing flowering in short-day plants is the length of the uninterrupted dark period, which is disrupted by the light flash.', options: AR_OPTIONS, correctIndex: 0, explanation: 'Since it is the length of uninterrupted darkness that matters, breaking the dark period with light disrupts the signal needed for flowering, correctly supporting the assertion.', difficulty: 'hard' },
  { id: 'p14', topic: 'photoperiodism', type: 'mcq', question: 'A hypothetical flowering hormone, thought to be produced in the leaves and transported to the apex to induce flowering, has been proposed and is called', options: ['Vernalin', 'Florigen', 'Zeatin', 'Auxin'], correctIndex: 1, explanation: 'Florigen is the hypothetical flowering hormone/signal proposed to move from leaves to the shoot apex to trigger flowering.', difficulty: 'medium' },
  { id: 'p15', topic: 'photoperiodism', type: 'mcq', question: 'The photoperiodic response in plants is perceived by leaves and then results in flowering at the', options: ['Root tip', 'Shoot apex', 'Leaf itself, with no signal transmission needed', 'Root hairs'], correctIndex: 1, explanation: 'Although perception occurs in leaves, the flowering response manifests at the shoot apex, implying a signal is transmitted between the two.', difficulty: 'medium' },
  { id: 'p16', topic: 'photoperiodism', type: 'mcq', question: 'A short-day plant with a critical photoperiod of, say, 14 hours will flower when the day length is', options: ['Equal to or longer than 14 hours', 'Equal to or shorter than 14 hours', 'Exactly 24 hours', 'Zero hours only'], correctIndex: 1, explanation: 'Short-day plants flower when the photoperiod is equal to or shorter than their species-specific critical day length.', difficulty: 'medium' },
  { id: 'p17', topic: 'photoperiodism', type: 'statement', question: 'Consider the following statements about photoperiodism:\n1. The photoperiodic stimulus is perceived by the leaves.\n2. Phytochrome is the main photoreceptor pigment involved.\n3. All plants require a specific photoperiod to flower.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '2 and 3 only', '1 and 3 only', '1, 2 and 3'], correctIndex: 0, explanation: 'Statements 1 and 2 are correct; day-neutral plants flower regardless of photoperiod, so statement 3 is incorrect.', difficulty: 'medium' },
  { id: 'p18', topic: 'photoperiodism', type: 'count-correct', question: 'How many of the following are correctly matched with their photoperiodic category?\n(i) Chrysanthemum — Short-day plant\n(ii) Spinach — Long-day plant\n(iii) Tomato — Day-neutral plant\n(iv) Tobacco — Long-day plant', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Chrysanthemum-short day, spinach-long day, and tomato-day neutral are correctly matched; tobacco is actually a short-day plant, not long-day.', difficulty: 'medium' },
  { id: 'p19', topic: 'photoperiodism', type: 'mcq', question: 'A change in photoperiod experienced due to seasonal variation is a key environmental cue that helps synchronise', options: ['Root growth alone', 'Flowering time with favourable seasonal conditions', 'Seed coat colour', 'Leaf shape only'], correctIndex: 1, explanation: 'Photoperiodic responses help plants time their flowering to coincide with favourable seasonal conditions for reproduction.', difficulty: 'medium' },
  { id: 'p20', topic: 'photoperiodism', type: 'mcq', question: 'Which of the following statements about long-day plants is correct?', options: ['They flower when night length exceeds a critical duration', 'They flower when day length exceeds (or night length is shorter than) a critical duration', 'They never flower regardless of day length', 'They are unaffected by interruption of the dark period'], correctIndex: 1, explanation: 'Long-day plants flower when day length exceeds the critical duration (equivalently, when the night is shorter than a critical length).', difficulty: 'medium' },
  { id: 'p21', topic: 'photoperiodism', type: 'mcq', question: 'Vernalization is defined as', options: ['The promotion of flowering by exposure to low temperature', 'The promotion of flowering by exposure to specific day length', 'The suppression of seed germination by cold', 'The prevention of flowering permanently'], correctIndex: 0, explanation: 'Vernalization refers to the promotion of flowering by a period of low-temperature treatment.', difficulty: 'easy' },
  { id: 'p22', topic: 'photoperiodism', type: 'mcq', question: 'The scientist most closely associated with early studies and the coining of the term "vernalization" is', options: ['Went', 'Lysenko', 'Garner', 'Skoog'], correctIndex: 1, explanation: 'Lysenko is credited with coining the term vernalization and conducting influential early studies on cold-induced flowering.', difficulty: 'medium' },
  { id: 'p23', topic: 'photoperiodism', type: 'mcq', question: 'Vernalization is especially important in preventing precocious reproductive development in', options: ['Annual plants only', 'Biennial and winter annual plants like winter wheat and rye', 'Day-neutral fruits only', 'Aquatic plants only'], correctIndex: 1, explanation: 'Vernalization helps prevent precocious flowering in biennials and winter annual crops such as winter wheat and rye, aligning flowering with spring.', difficulty: 'medium' },
  { id: 'p24', topic: 'photoperiodism', type: 'mcq', question: 'Winter varieties of wheat, if sown in spring without a preceding cold treatment, typically', options: ['Flower and produce seeds normally', 'Fail to flower or flower very late, since they lack the required vernalization', 'Grow faster than usual', 'Show no effect on flowering at all'], correctIndex: 1, explanation: 'Without a preceding cold treatment, winter wheat varieties fail to flower properly, as they require vernalization to trigger the flowering transition.', difficulty: 'medium' },
  { id: 'p25', topic: 'photoperiodism', type: 'mcq', question: 'By artificially vernalizing (cold-treating) winter wheat seeds before spring sowing, farmers are able to', options: ['Grow winter wheat as a spring crop, harvesting before the onset of winter', 'Prevent flowering altogether', 'Increase seed dormancy indefinitely', 'Eliminate the need for photoperiodic conditions'], correctIndex: 0, explanation: 'Vernalizing seeds artificially allows winter wheat to be grown as a spring-sown crop, flowering and being harvested before winter arrives.', difficulty: 'medium' },
  { id: 'p26', topic: 'photoperiodism', type: 'mcq', question: 'Vernalization is generally understood to act by', options: ['Removing chlorophyll from the leaves', 'Inducing a physiological change (often linked with a shift in gene expression) that is required before flowering can occur', 'Increasing the number of stomata', 'Preventing photosynthesis entirely'], correctIndex: 1, explanation: 'Vernalization induces underlying physiological (and molecular/gene expression) changes that are prerequisites for flowering in vernalization-requiring plants.', difficulty: 'hard' },
  { id: 'p27', topic: 'photoperiodism', type: 'assertion-reason', question: 'Assertion (A): Vernalization ensures winter cereals do not flower too early during the winter season.\nReason (R): The requirement for a period of cold exposure before flowering acts as a check that prevents premature reproductive development.', options: AR_OPTIONS, correctIndex: 0, explanation: 'The cold requirement acting as a checkpoint before flowering directly explains how vernalization prevents premature flowering, supporting the assertion.', difficulty: 'medium' },
  { id: 'p28', topic: 'photoperiodism', type: 'mcq', question: 'The vernalization effect, once induced by cold treatment, can sometimes be reversed by a subsequent exposure to', options: ['High light intensity', 'High temperature shortly after the cold treatment (devernalization)', 'Long photoperiods only', 'High humidity'], correctIndex: 1, explanation: 'The vernalized state can be lost through devernalization, which can occur if plants are exposed to high temperatures soon after cold treatment.', difficulty: 'hard' },
  { id: 'p29', topic: 'photoperiodism', type: 'mcq', question: 'Which of the following best distinguishes photoperiodism from vernalization?', options: ['Photoperiodism responds to day/night length, while vernalization responds to a period of low temperature', 'Both respond only to temperature', 'Both respond only to day length', 'They are simply two names for the exact same process'], correctIndex: 0, explanation: 'Photoperiodism concerns responses to relative day/night length, while vernalization concerns the promotion of flowering by cold treatment — two distinct environmental cues.', difficulty: 'medium' },
  { id: 'p30', topic: 'photoperiodism', type: 'statement', question: 'Consider the following statements about vernalization:\n1. It refers to flowering promotion by cold treatment.\n2. It is particularly relevant to biennial plants like winter wheat.\n3. Vernalization and photoperiodism refer to the exact same phenomenon.\nWhich of the statements given above are correct?', options: ['1 and 2 only', '2 and 3 only', '1 and 3 only', '1, 2 and 3'], correctIndex: 0, explanation: 'Statements 1 and 2 are correct; vernalization and photoperiodism are distinct phenomena responding to different cues (temperature vs. day length), so statement 3 is incorrect.', difficulty: 'medium' },
  { id: 'p31', topic: 'photoperiodism', type: 'count-correct', question: 'How many of the following statements about vernalization are correct?\n(i) It involves exposure of seeds or seedlings to low temperature.\n(ii) It is particularly relevant for winter annual/biennial crops.\n(iii) It can be reversed by high-temperature exposure shortly afterward (devernalization).\n(iv) It is identical to photoperiodism.', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements (i), (ii), and (iii) are correct; vernalization is distinct from photoperiodism, so statement (iv) is incorrect.', difficulty: 'hard' },
  { id: 'p32', topic: 'photoperiodism', type: 'mcq', question: 'Which of the following crops is a classic example requiring vernalization for normal flowering?', options: ['Rice', 'Winter wheat/rye', 'Maize', 'Tomato'], correctIndex: 1, explanation: 'Winter wheat and rye are classic examples of crops requiring a cold treatment (vernalization) to flower normally.', difficulty: 'medium' },
  { id: 'p33', topic: 'photoperiodism', type: 'mcq', question: 'In some biennial plants that show a rosette growth habit before flowering, both vernalization and subsequent photoperiodic signals may be required for', options: ['Seed germination alone', 'The full sequence of bolting and flowering', 'Root formation', 'Leaf abscission'], correctIndex: 1, explanation: 'Some biennials require sequential vernalization and photoperiodic cues to trigger bolting and flowering.', difficulty: 'hard' },
  { id: 'p34', topic: 'photoperiodism', type: 'mcq', question: 'The overall significance of photoperiodism and vernalization for agriculture lies mainly in', options: ['Their irrelevance to crop scheduling', 'Enabling farmers to time sowing and manipulate flowering for better crop yield and adaptation to climate', 'Only affecting ornamental ptotany with no crop relevance', 'Preventing all flowering in crop plants'], correctIndex: 1, explanation: 'Understanding photoperiodism and vernalization allows farmers to schedule sowing and manipulate flowering time for improved yield and climatic adaptation.', difficulty: 'medium' },
  { id: 'p35', topic: 'photoperiodism', type: 'mcq', question: 'A plant that requires both an appropriate photoperiod and a preceding period of cold exposure to flower shows', options: ['Only a photoperiodic response', 'Only a vernalization response', 'A combined requirement of vernalization followed by an appropriate photoperiod', 'No environmental sensitivity at all'], correctIndex: 2, explanation: 'Some plants require both vernalization and a subsequent suitable photoperiod in sequence before they can flower.', difficulty: 'hard' },
  { id: 'p36', topic: 'photoperiodism', type: 'mcq', question: 'Which statement about phytochrome and photoperiodism is most accurate?', options: ['Phytochrome exists in two interconvertible forms responsive to red and far-red light, involved in perceiving photoperiod', 'Phytochrome has no role in photoperiodic responses', 'Phytochrome is only found in root tissue', 'Phytochrome only affects fruit ripening'], correctIndex: 0, explanation: 'Phytochrome exists in red-light-absorbing (Pr) and far-red-light-absorbing (Pfr) interconvertible forms, playing a central role in photoperiodic perception.', difficulty: 'hard' },
  { id: 'p37', topic: 'photoperiodism', type: 'mcq', question: 'Grafting experiments, where a leaf from a photoperiodically induced plant is grafted onto a non-induced plant of the same species, have shown that', options: ['The non-induced plant never flowers regardless of grafting', 'The non-induced plant can be induced to flower, supporting the idea of a mobile floral signal', 'Grafting has no observable effect', 'The leaf immediately dies after grafting with no further effect'], correctIndex: 1, explanation: 'Such grafting experiments demonstrate that a flower-inducing signal can move from an induced leaf to a non-induced plant, supporting the florigen concept.', difficulty: 'hard' },
  { id: 'p38', topic: 'photoperiodism', type: 'matching', question: 'Match the term in Column I with its correct description in Column II.\nColumn I: A. Short-day plant, B. Long-day plant, C. Day-neutral plant, D. Vernalization\nColumn II: (i) Flowering unaffected by photoperiod, (ii) Flowering promoted by cold treatment, (iii) Flowers when day length exceeds critical value, (iv) Flowers when day length is below critical value', options: ['A-iv, B-iii, C-i, D-ii', 'A-i, B-ii, C-iii, D-iv', 'A-iii, B-iv, C-ii, D-i', 'A-iv, B-i, C-iii, D-ii'], correctIndex: 0, explanation: 'Short-day plant = flowers below critical day length; long-day plant = flowers above critical day length; day-neutral = unaffected; vernalization = cold-induced flowering promotion.', difficulty: 'medium' },
  { id: 'p39', topic: 'photoperiodism', type: 'mcq', question: 'The critical photoperiod is best defined as the', options: ['Exact number of hours of light a plant always needs regardless of species', 'Duration of light (or dark) period that determines whether a photoperiod-sensitive plant will flower', 'The temperature threshold for vernalization', 'A fixed universal value of 12 hours for all plants'], correctIndex: 1, explanation: 'The critical photoperiod is the specific duration of light or darkness that determines the flowering response in photoperiod-sensitive plants, and it varies by species.', difficulty: 'medium' },
  { id: 'p40', topic: 'photoperiodism', type: 'mcq', question: 'Overall, photoperiodism and vernalization are best understood as mechanisms that allow plants to', options: ['Ignore environmental signals entirely', 'Synchronise developmental transitions, such as flowering, with favourable environmental and seasonal conditions', 'Prevent growth under all conditions', 'Only affect vegetative growth, never reproduction'], correctIndex: 1, explanation: 'Both mechanisms help plants time key developmental transitions like flowering to coincide with environmentally favourable periods.', difficulty: 'medium' },
];
